import{z as l,x as s,o as e,c as i,q as A,j as B,D as a,d as o,s as r,S as n}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"成本的组成与口径","description":"","frontmatter":{"title":"成本的组成与口径","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ce-cost-components.md","filePath":"llm/ce-cost-components.md","lastUpdated":1791413859000}'),p={name:"llm/ce-cost-components.md"};function m(c,E,d,F,_,C){const t=s("Mermaid");return e(),i("div",null,[E[2]||(E[2]=A('<h1 id="成本的组成与口径" tabindex="-1">成本的组成与口径 <a class="header-anchor" href="#成本的组成与口径" aria-label="Permalink to &quot;成本的组成与口径&quot;">​</a></h1><div class="epigraph"><p>成本从来不是账单上的一个数，而是几笔不同质的账；把哪一笔当成了「成本」，决定了你优化的对象和省下来的钱。</p><footer>—— 据 Pope et al., Efficiently Scaling Transformer Inference, MLSys 2023 与本仓库 KV 成本模型课的记账口径整理</footer></div><p><a href="/llm/pf2-map">上一课</a>把预训练实践配方收成一张图：开工前定地基、训练中守过程、收束管交付与复盘，三条不变量是判据先行、口径同源、旋钮可指认。成本工程沿用同一条纪律：先钉口径，再谈杠杆。本课是「推理成本工程」课程的第一课：把账本身拆开——推理的成本由哪些项组成、用哪种口径说出来才算数。后课默认这些口径已经钉死，直接在口径上谈杠杆与治理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三个数都被人叫作「成本」：API 账单上的月费、GPU 的时租、报价表上的每百万 token。它们不同质：月费是结算口径，时租是资源口径，每百万 token 是业务口径。缺口不是找一个更准的数，而是先把组成拆开、把口径钉死。不拆开的错法很常见：把时租除以当天生成的 token 数得出「单价」，第二天流量掉一半，单价翻倍，于是得出「模型变贵了」的误判——变的是利用率，不是价格；照着这个误判去换模型或砍服务，省不下任何东西。</p><p><span class="marginnote">数字实例：设一张卡一天的租金固定为 48 美元。高峰日生成 100 万 token，「单价」算出来是 48 美元/百万；次日流量减半，时租照付，「单价」就变成 96 美元/百万——价目表上一个字都没改，变的只是利用率。</span></p><h3 id="四笔不同质的账" tabindex="-1">四笔不同质的账 <a class="header-anchor" href="#四笔不同质的账" aria-label="Permalink to &quot;四笔不同质的账&quot;">​</a></h3><p>单请求成本写成四项之和：</p> \\[c_{\\rm req} = \\frac{c_{\\rm w}}{N_{\\rm req}} + c_{\\rm mem}\\int_0^T M(t)\\,dt + c_{\\rm bw}\\,B + c_{\\rm fix} \\]<p>权重摊销按请求摊，容量积分按字节·秒计，带宽搬运按字节·步计，固定开销（调度、采样、网络、重试）按次计。<a href="/llm/kv-cost-model">KV 成本模型课</a>已把四笔账的单位钉过：混报就无法优化——把容量账摊进带宽账，驱逐策略的收益就在报数里凭空消失。本课只补一句：每一项的驱动变量不同，权重的 \\(N_{\\rm req}\\)、容量的会话时长、带宽的序列长度、固定的重试率，各自对应完全不同的旋钮。</p>',10)),(e(),B(n,null,{default:a(()=>[r(t,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20COST%5B%22%E5%8D%95%E8%AF%B7%E6%B1%82%E6%88%90%E6%9C%AC%22%5D%20--%3E%20W%5B%22%E6%9D%83%E9%87%8D%E6%91%8A%E9%94%80%EF%BC%9A%E6%8C%89%E8%AF%B7%E6%B1%82%22%5D%0A%20%20COST%20--%3E%20M%5B%22%E5%AE%B9%E9%87%8F%E7%A7%AF%E5%88%86%EF%BC%9A%E5%AD%97%E8%8A%82%C2%B7%E7%A7%92%22%5D%0A%20%20COST%20--%3E%20B%5B%22%E5%B8%A6%E5%AE%BD%E6%90%AC%E8%BF%90%EF%BC%9A%E5%AD%97%E8%8A%82%C2%B7%E6%AD%A5%22%5D%0A%20%20COST%20--%3E%20F%5B%22%E5%9B%BA%E5%AE%9A%E5%BC%80%E9%94%80%EF%BC%9A%E9%87%8D%E8%AF%95%E4%B8%8E%E8%B0%83%E5%BA%A6%22%5D%0A%20%20W%20--%3E%20OUT%5B%22%E4%B8%89%E7%A7%8D%E5%8F%A3%E5%BE%84%E6%8D%A2%E7%AE%97%22%5D%0A%20%20M%20--%3E%20OUT%0A%20%20B%20--%3E%20OUT%0A%20%20F%20--%3E%20OUT%0A%20%20OUT%20--%3E%20PER%5B%22%E6%AF%8F%E8%AF%B7%E6%B1%82%22%5D%0A%20%20OUT%20--%3E%20MTOK%5B%22%E6%AF%8F%E7%99%BE%E4%B8%87%20token%22%5D%0A%20%20OUT%20--%3E%20UTIL%5B%22%E6%AF%8F%E5%B0%8F%E6%97%B6%E5%88%A9%E7%94%A8%E7%8E%87%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[o(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>口径是账到业务语言的换算。三种口径各答一个问题：每请求口径答「一次服务多少钱」，定价与免费层看它；每百万 token 口径答「单位产出多少钱」，选型与基准看它；利用率口径答「买来的资源用了几成」，容量与采购看它。换算公式只有一条，但必须带窗口：</p> \\[c_{\\rm Mtok} = \\frac{\\text{窗口内总成本}}{\\text{窗口内计费 token 总量}}\\times 10^6 \\]<p>写法上，每一笔账要同时记数值、单位与测量窗口。缺窗口的单价不可比：高峰时段与深夜空转的单价可以差十倍，而它们出自同一张卡、同一个模型。这也是<a href="/llm/cost-per-mtok">百万 token 成本课</a>反复强调的：对外报价与对内芯片·秒/token 是两套口径，不能互换。</p><p><span class="marginnote">直觉类比：同一趟出租车可以报三个数——这一单收了 30 元（每请求口径），除以里程是 3 元/公里（每百万 token 口径），再加上「今天有载客的时间占几成」（利用率口径）。三个数都正确，答的是三个不同的问题，谁也代替不了谁。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>口径决定优化对象，这是本课程全部杠杆的坐标系。每请求口径上，优化对象是请求数与请求形状——缓存、路由、级联都在这里起作用；每百万 token 口径上，优化对象是每个 token 摊到的字节与算力——量化、批、投机解码在这里；利用率口径上，优化对象是打满率——调度、混部、弹性伸缩在这里。混用口径的错误各有形态：用利用率口径的单价去评缓存优化，会看见「单价没降」，因为缓存省下的是 prefill 算力，省出的容量被新请求挤占，打满率反而上升——账上每请求成本降了，时租口径纹丝不动，两笔都对，混着读必然读错一个。</p>',7)),(e(),B(n,null,{default:a(()=>[r(t,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20LR%0A%20%20P%5B%22%E6%AF%8F%E8%AF%B7%E6%B1%82%E5%8F%A3%E5%BE%84%22%5D%20--%3E%20O1%5B%22%E4%BC%98%E5%8C%96%E5%AF%B9%E8%B1%A1%EF%BC%9A%E8%AF%B7%E6%B1%82%E6%95%B0%E4%B8%8E%E8%AF%B7%E6%B1%82%E5%BD%A2%E7%8A%B6%22%5D%0A%20%20MT%5B%22%E6%AF%8F%E7%99%BE%E4%B8%87%20token%20%E5%8F%A3%E5%BE%84%22%5D%20--%3E%20O2%5B%22%E4%BC%98%E5%8C%96%E5%AF%B9%E8%B1%A1%EF%BC%9A%E6%AF%8F%20token%20%E6%91%8A%E5%88%B0%E7%9A%84%E5%AD%97%E8%8A%82%E4%B8%8E%E7%AE%97%E5%8A%9B%22%5D%0A%20%20U%5B%22%E5%88%A9%E7%94%A8%E7%8E%87%E5%8F%A3%E5%BE%84%22%5D%20--%3E%20O3%5B%22%E4%BC%98%E5%8C%96%E5%AF%B9%E8%B1%A1%EF%BC%9A%E6%89%93%E6%BB%A1%E7%8E%87%22%5D%0A%20%20O1%20--%3E%20L1%5B%22%E7%BC%93%E5%AD%98%20%2F%20%E8%B7%AF%E7%94%B1%20%2F%20%E7%BA%A7%E8%81%94%22%5D%0A%20%20O2%20--%3E%20L2%5B%22%E9%87%8F%E5%8C%96%20%2F%20%E6%89%B9%20%2F%20%E6%8A%95%E6%9C%BA%E8%A7%A3%E7%A0%81%22%5D%0A%20%20O3%20--%3E%20L3%5B%22%E8%B0%83%E5%BA%A6%20%2F%20%E6%B7%B7%E9%83%A8%20%2F%20%E5%BC%B9%E6%80%A7%E4%BC%B8%E7%BC%A9%22%5D%0A%20%20L1%20--%3E%20WARN%5B%22%E6%B7%B7%E8%AF%BB%E5%8F%A3%E5%BE%84%EF%BC%9A%E7%9C%81%E4%B8%8B%E7%9A%84%E9%92%B1%E5%9C%A8%E5%88%AB%E7%9A%84%E8%B4%A6%E4%B8%8A%E7%9C%8B%E4%B8%8D%E8%A7%81%22%5D%0A%20%20L2%20--%3E%20WARN%0A%20%20L3%20--%3E%20WARN%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[o(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p><span class="marginnote">例：一张卡时租固定，当天只有一成时间在算，「每百万 token 成本」是打满时的十倍。报单价必须同时报测量窗口与打满率，否则这个数什么都不能比较。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>定价不是成本：API 的折扣价、批量价、缓存折扣价是商业口径，与自建集群的单价不同质，跨口径比较要先换算成同一单位。口径还要带版本戳：模型换代、tokenizer 更换、硬件代际切换都会让旧数字失效，成本数字只对当时的配置负责。最后，四笔账里没有质量项——本课程把质量做成独立的合同约束，放在收束前的<a href="/llm/ce-cost-quality-contract">成本与质量的合同</a>课里，那里会引用本课的口径。</p><p><span class="marginnote">常见误区：初学者容易拿 API 折扣价直接对比自建集群的单价。定价是商业口径，含利润、补贴与批量折扣；芯片·秒/token 是物理口径，含利用率假设。两者不同质，跨口径比较前必须先换算到同一单位、同一测量窗口，否则比出来的「便宜」没有意义。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>推理成本是四笔不同质的账：权重摊销、容量积分、带宽搬运、固定开销，驱动变量各不相同。</li><li>三种口径各有用途：每请求答定价、每百万 token 答选型、利用率答采购，换算必须带测量窗口。</li><li>口径决定优化对象：请求形状、单位字节、打满率分别对应本课程三个单元的杠杆。</li><li>混报口径的误判可预测：利用率波动会被误读成价格变化，容量收益会在带宽账里消失。</li><li>出处：Pope et al., 2022（阶段拆分与芯片·秒口径）；四笔账单位沿用本仓库 KV 成本模型课，不另造文献。</li></ul>',6))])}const T=l(p,[["render",m]]);export{D as __pageData,T as default};
